/**
 * Advance width of `text` in em, at `weight`, in the family behind `key`.
 *
 * An unknown character falls back to `defaultAdvance` for its class rather than
 * to zero: a missing glyph is a real width in the render, and a table that
 * returns 0 for it is a table that will happily overflow a column.
 */
export function advanceEm(key: FontMetricKey, weight: number, text: string): number {
  const metrics = FONT_METRICS[key];
  const byWeight = metrics.weights[String(weight)] ?? metrics.weights[Object.keys(metrics.weights)[0]!]!;
  let total = 0;
  for (const ch of text) total += byWeight[ch] ?? byWeight["n"] ?? 0.6;
  return total;
}

/** The character measured when nothing else is. Used only as a last resort. */
export const DEFAULT_ADVANCE_EM = 0.6;
